function defaultSave(){return {version:3,event:{tasks:{},claimed:false},name1:'Angèle',name2:'Adrien',xp:0,coins:20,hearts:0,completed:{},started:{},notes:[],mood:'surprise'};}
function load(){try{const raw=localStorage.getItem(KEY); if(!raw) return defaultSave(); const data=JSON.parse(raw); return {...defaultSave(),...data,event:{tasks:{},claimed:false,...(data.event||{})},name1:(data.name1||'Angèle').slice(0,24),name2:(data.name2||'Adrien').slice(0,24)};}catch{return defaultSave()}}
let state=load();
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(v){return String(v??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function hash(str){let h=2166136261; for(let i=0;i<str.length;i++){h^=str.charCodeAt(i); h += (h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24);} return Math.abs(h>>>0)}
function dateKey(){const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function level(){return Math.max(1,Math.floor(state.xp/220)+1)}
function xpMinForLevel(lv){return (lv-1)*220}
function xpMaxForLevel(lv){return lv*220}
function nextProgress(){const cur=state.xp-xpMinForLevel(level()); const max=xpMaxForLevel(level())-xpMinForLevel(level()); return {cur,max,pct:Math.max(0,Math.min(100,Math.round((cur/max)*100)))}}
function completeCount(){return Object.keys(state.completed).length}
function doneQuest(q){return !!state.completed[q.id]}
function unlocked(q){return level()>=q.unlock}
function cityCount(city){return QUESTS.filter(q=>q.city===city && doneQuest(q)).length}
function flandersCount(){return QUESTS.filter(q=>['Steenvoorde','Flandre','Région'].includes(q.city) && doneQuest(q)).length}
function groupCount(group){return QUESTS.filter(q=>q.group===group && doneQuest(q)).length}
function totalHearts(){return Math.max(Number(state.hearts)||0,QUESTS.filter(q=>doneQuest(q)).reduce((s,q)=>s+(q.hearts||0),0))}
function badgeIds(){const set=new Set(); QUESTS.forEach(q=>{if(doneQuest(q) && q.badge) set.add(q.badge);}); ACHIEVEMENTS.forEach(a=>{if(a.get()>=a.goal) set.add(a.id);}); return [...set];}
function badgeCount(){return badgeIds().length}
function dailyOracle(){return ORACLES[hash(dateKey())%ORACLES.length]}
function questById(id){return QUESTS.find(q=>q.id===id)}
function seededShuffle(arr,seed){const a=arr.slice(); let s=hash(seed)||1; function rnd(){s=(s*1664525+1013904223)%4294967296; return s/4294967296;} for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1)); [a[i],a[j]]=[a[j],a[i]];} return a;}
function dailyQuests(){const pool=QUESTS.filter(q=>unlocked(q)); const fresh=pool.filter(q=>!doneQuest(q)); return seededShuffle(fresh.length?fresh:pool,dateKey()).slice(0,3);}
function featuredEpic(){return QUESTS.filter(q=>q.group==='epique' && unlocked(q)).sort((a,b)=>(doneQuest(a)-doneQuest(b)) || b.xp-a.xp)[0] || QUESTS.find(q=>q.group==='epique')}
function recommendByMood(){const list=QUESTS.filter(q=>unlocked(q) && !doneQuest(q) && q.moods.includes(state.mood)); return list.sort((a,b)=>a.unlock-b.unlock || a.minutes-b.minutes)[0] || dailyQuests()[0];}
function regionProgress(region){if(region==='Lille') return cityCount('Lille'); if(region==='Douai') return cityCount('Douai'); return flandersCount();}
function notify(text){document.querySelector('.toast')?.remove(); const el=document.createElement('div'); el.className='toast'; el.textContent=text; document.body.appendChild(el); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.remove(),2400);}
function statCard(icon,val,label){return `<div class="stat"><span class="ico">${icon}</span><b>${val}</b><small>${label}</small></div>`}
function tags(q){return `<div class="tags"><span class="tag">◷ ${q.minutes} min</span><span class="tag dark">${esc(q.cost===0?'Gratuit':'Budget ≈ '+q.cost+' €')}</span><span class="tag gold">+${q.xp} XP</span>${q.hearts?`<span class="tag rose">+${q.hearts} cœur${q.hearts>1?'s':''}</span>`:''}</div>`}
function topHome(){const prog=nextProgress(); return `<header class="top"><div class="leaves">❦</div><div class="leaves right">❦</div><div class="brandline"><div class="brandmark"><div class="logo">✦</div><div><div class="eyebrow">Aventure à deux</div><div class="brandtitle">Duo Quest</div></div></div><button class="roundbtn" data-nav="settings">⚙️</button></div><div class="hero-copy"><div class="eyebrow">Bonjour ${esc(state.name1)} &amp; ${esc(state.name2)}</div><h1>Votre quotidien devient une aventure.</h1><p>Des quêtes autour de Lille, Douai et des Flandres, des souvenirs à garder et une progression pensée pour vous donner envie de sortir… ou de rester bien ensemble.</p></div><div class="hero-scene"><div class="sun"></div><div class="cloud c1"></div><div class="cloud c2"></div><div class="cloud c3"></div><div class="sparkles">✦ ✦ ✦</div><div class="hill one"></div><div class="hill two"></div><div class="hill three"></div><div class="belfry"></div><div class="windmill"></div><div class="travellers"><span class="person p1"><span class="bag"></span></span><span class="person p2"><span class="bag"></span></span></div><div class="hero-stats"><div class="level-chip"><b>Niveau ${level()}</b><small>${prog.cur} / ${prog.max} XP vers le prochain niveau</small><div class="xpmini"><span style="width:${prog.pct}%"></span></div></div><div class="crest">♡</div></div></div></header>`;}
function topSimple(title,subtitle){return `<header class="top"><div class="leaves">❦</div><div class="leaves right">❦</div><div class="brandline"><div class="brandmark"><div class="logo">✦</div><div><div class="eyebrow">Duo Quest</div><div class="brandtitle">${esc(title)}</div></div></div><button class="roundbtn" data-nav="home">⌂</button></div><div class="hero-copy" style="max-width:100%"><h1 style="font-size:30px">${esc(title)}</h1><p>${esc(subtitle)}</p></div></header>`;}
function questCard(q){return `<article class="quest ${doneQuest(q)?'done':''} ${!unlocked(q)?'locked':''}"><button class="questbutton" data-open="${q.id}"><div class="art theme-${q.theme}"><span class="emoji">${q.emoji}</span></div><div class="info"><div class="eyebrow" style="color:#9b7b43">${esc(q.kind)} · ${esc(q.city)}</div><h3>${esc(q.title)}${doneQuest(q)?' ✓':''}</h3><p>${esc(q.place)}${!unlocked(q)?` · Débloqué au niveau ${q.unlock}`:''}</p>${tags(q)}</div></button></article>`;}

const RELEASE = new Date('2026-11-19T00:00:00+01:00').getTime();
