function eventToggle(id){
 const task=EVENT_TASKS.find(x=>x.id===id);if(!task)return;
 if(task.id==='d4'&&!eventTimer().released){notify('Cette étape se débloque jeudi 19 novembre ♡');return;}
 state.event??={tasks:{},claimed:false};state.event.tasks??={};
 if(state.event.tasks[id]){notify('Mission déjà validée : impossible de gagner deux fois la récompense.');return;}
 state.event.tasks[id]=true;state.xp+=35;state.coins+=10;save();render();notify('Mission accomplie ! +35 XP et +10 pièces ✦');
}
function eventReward(){if(eventCount()!==EVENT_TASKS.length||state.event?.claimed)return;state.event.claimed=true;state.xp+=180;state.coins+=80;save();render();notify('Coffre ouvert ! +180 XP et +80 pièces ♡');}
function home(){const rec=recommendByMood(); const daily=dailyQuests(); const epic=featuredEpic(); return topHome()+v4Dashboard()+`<div class="container"><div class="duo-banner"><div class="topline"><div><div class="eyebrow" style="color:#99743a">Le duo du jour</div><h2>${esc(state.name1)} &amp; ${esc(state.name2)}</h2><p>Un jeu d'aventure local, sans compte, sans pub et avec de vrais souvenirs à créer ensemble.</p></div><button class="pill" data-nav="journal">Voir nos badges</button></div><div class="statgrid">${statCard('⭐',state.xp,'XP total')}${statCard('🪙',state.coins,'Pièces')}${statCard('♡',totalHearts(),'Cœurs')}${statCard('♜',badgeCount(),'Badges')}</div></div>${eventMini()}<div class="sectionrow"><h2>Notre humeur</h2><div class="subline">Pour vous suggérer la bonne sortie</div></div><div class="moods">${[['surprise','Surprise ✦'],['douceur','Douceur'],['balade','Balade'],['gourmand','Gourmand'],['mystere','Mystère'],['cocon','Cocon'],['epique','Épique']].map(([id,label])=>`<button class="pill ${state.mood===id?'active':''}" data-mood="${id}">${label}</button>`).join('')}</div><div class="suggestion"><div class="eyebrow" style="color:#9d7d43">Boussole du duo</div><h3>On vous conseille : ${esc(rec.title)}</h3><p>${esc(rec.place)} · ${rec.minutes} min · ${rec.cost===0?'gratuit':'budget ≈ '+rec.cost+' €'}.</p><div class="rowgap" style="margin-top:12px"><button class="mainbtn" data-open="${rec.id}">Découvrir la quête</button><button class="secondary" data-nav="quests">Voir toutes</button></div></div><div class="sectionrow"><h2>Oracle du jour</h2><div class="subline">Une petite touche de magie</div></div><div class="oracle"><div class="eyebrow">Message d'ambiance</div><h3>✦ Votre présage</h3><p>${esc(dailyOracle())}</p></div><div class="sectionrow"><h2>Quêtes du jour</h2><button class="link" data-nav="quests">Voir tout</button></div>${daily.map(questCard).join('')}<div class="sectionrow"><h2>Progression de région</h2><div class="subline">Vos traces dans le Nord</div></div><div class="region-grid"><div class="region-card"><span>🕍</span><b>Lille</b><small>${regionProgress('Lille')} quêtes</small></div><div class="region-card"><span>🔔</span><b>Douai</b><small>${regionProgress('Douai')} quêtes</small></div><div class="region-card"><span>🌾</span><b>Flandres</b><small>${regionProgress('Flandres')} quêtes</small></div></div><div class="sectionrow"><h2>Grande aventure mise en avant</h2><div class="subline">Pour les jours qui comptent</div></div><div class="feature-card"><div class="eyebrow" style="color:#9d7d43">Épopée</div><h3>${esc(epic.title)}</h3><p>${esc(epic.place)} · Une aventure plus riche, plus longue, parfaite pour créer un vrai souvenir de duo.</p><div style="margin-top:10px">${tags(epic)}</div><button class="mainbtn" style="margin-top:14px" data-open="${epic.id}">Voir cette aventure</button></div><div class="sectionrow"><h2>Camp de base</h2><div class="subline">Vos outils du quotidien</div></div><div class="summary-grid"><div class="summary-card"><small>EXPORT</small><b>Sauvegarde</b><p>Conservez votre aventure dans un fichier.</p><button class="softbtn" style="margin-top:12px" data-action="export">Exporter</button></div><div class="summary-card"><small>NOMS</small><b>Votre duo</b><p>Personnalisez les noms visibles dans l'app.</p><button class="softbtn" style="margin-top:12px" data-nav="settings">Réglages</button></div></div></div>`;}
function questsView(){const filters=[['all','Toutes'],['Lille','Lille'],['Douai','Douai'],['flandres','Flandres'],['Maison','Maison'],['epique','Épiques']]; let list=QUESTS.filter(q=>filter==='all'?true:filter==='flandres'?(q.city==='Steenvoorde'||q.city==='Flandre'||q.city==='Région'):filter==='epique'?q.group==='epique':q.city===filter); list=list.sort((a,b)=>{const ua=unlocked(a)?0:1, ub=unlocked(b)?0:1, da=doneQuest(a)?1:0, db=doneQuest(b)?1:0; return ua-ub || da-db || a.unlock-b.unlock || b.xp-a.xp;}); return topSimple('Le grimoire des quêtes','Choisissez votre aventure selon l’humeur, le lieu ou l’énergie du jour.')+`<div class="container"><div class="filters">${filters.map(([id,label])=>`<button class="pill ${filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><div class="notice">${QUESTS.filter(q=>unlocked(q) && !doneQuest(q)).length} quêtes actuellement disponibles à tenter. Les aventures plus épiques se débloquent en gagnant des niveaux.</div><div class="sectionrow"><h2>Quêtes</h2><div class="subline">${list.length} résultats</div></div>${list.map(questCard).join('')}</div>`;}
function atlas(){
 const picks={lille:questById('citadelle_lille'),douai:questById('beffroi_douai'),flandre:questById('moulin_steenvoorde'),epic:featuredEpic()};
 return topSimple('Explorer la région','Un atlas illustré pour découvrir votre prochain chapitre.')+`<div class="container">
 <div class="map-illustration">
  <img src="atlas.webp" alt="Carte d’aventure peinte de Lille, Douai et Steenvoorde : moulins, maisons, forêt, cours d’eau et chemins" draggable="false">
  <button class="map-hotspot spot-lille" data-open="${picks.lille.id}" aria-label="Découvrir les quêtes à Lille"><span>Lille</span></button>
  <button class="map-hotspot spot-douai" data-open="${picks.douai.id}" aria-label="Découvrir les quêtes à Douai"><span>Douai</span></button>
  <button class="map-hotspot spot-steenvoorde" data-open="${picks.flandre.id}" aria-label="Découvrir les quêtes à Steenvoorde"><span>Steenvoorde</span></button>
 </div>
 <div class="map-caption">✦ Touchez Lille, Douai ou Steenvoorde directement sur la carte. Carte artistique, pas un plan de navigation réel.</div>
 <div class="sectionrow"><h2>Portes d'aventure</h2><div class="subline">Votre prochain voyage à deux</div></div>
 ${[picks.lille,picks.douai,picks.flandre,picks.epic].map(questCard).join('')}
 <div class="oracle"><div class="eyebrow">Le conseil des voyageurs</div><h3>🌿 Un détour vaut parfois un trésor</h3><p>Les marqueurs ouvrent vos quêtes. Pour rejoindre les lieux, utilisez le bouton Plans dans la fiche mission.</p></div>
 </div>`;
}
function badgeCard(id,owned){const b=BADGES[id]||['🔒','À découvrir']; return `<div class="badgeitem ${owned?'':'locked'}"><span class="emoji">${owned?b[0]:'🔒'}</span><b>${owned?esc(b[1]):'À découvrir'}</b></div>`;}
function journal(){const owned=new Set(badgeIds()); const done=QUESTS.filter(q=>doneQuest(q)).sort((a,b)=>(state.completed[b.id]?.date||'').localeCompare(state.completed[a.id]?.date||'')); return topSimple('Notre histoire','Badges, souvenirs et grandes étapes de votre progression commune.')+`<div class="container"><div class="summary-grid"><div class="summary-card"><small>NIVEAU</small><b>${level()}</b><p>Une progression douce, sans punition et sans corvée.</p></div><div class="summary-card"><small>AVENTURES</small><b>${completeCount()}</b><p>Quêtes terminées avec succès à deux.</p></div></div><div class="sectionrow"><h2>Badges & souvenirs</h2><div class="subline">${owned.size} / ${Object.keys(BADGES).length}</div></div><div class="badgegrid">${Object.keys(BADGES).map(id=>badgeCard(id,owned.has(id))).join('')}</div><div class="sectionrow"><h2>Exploits en cours</h2><div class="subline">Encore un peu d’aventure</div></div>${ACHIEVEMENTS.map(a=>{const val=Math.min(a.goal,a.get()); const pct=Math.round((val/a.goal)*100); return `<div class="achievement"><small>${a.icon} ${esc(a.label)}</small><h3>${esc(a.label)}</h3><p>${esc(a.desc)} (${val} / ${a.goal})</p><div class="prog"><span style="width:${pct}%"></span></div></div>`;}).join('')}<div class="sectionrow"><h2>Journal de bord</h2><div class="subline">Vos plus beaux moments</div></div>${done.length ? done.map(q=>`<div class="setting"><h3>${q.emoji} ${esc(q.title)}</h3><div class="date">${new Date(state.completed[q.id].date).toLocaleDateString('fr-FR')} · +${q.xp} XP</div><p>${esc(state.completed[q.id].memory || 'Un souvenir doux de cette aventure.')}</p></div>`).join('') : `<div class="empty"><div class="big">📖</div>Le journal se remplira à mesure de vos aventures.</div>`}</div>`;}
function detail(q){if(!q) q=QUESTS[0]; if(!unlocked(q)) return topSimple('Mystère verrouillé','Continuez à jouer pour déverrouiller cette aventure.')+`<div class="container"><div class="empty"><div class="big">🔒</div>Cette quête se débloque au niveau ${q.unlock}. Vous êtes actuellement niveau ${level()}.</div><button class="mainbtn" data-nav="quests">Retour aux quêtes</button></div>`; const checked=state.started[q.id]||[]; const done=doneQuest(q); const all=q.steps.every((_,i)=>checked.includes(i)); return topSimple('Journal de mission','Préparez-vous, validez les étapes et gardez un souvenir.')+`<div class="container detail"><button class="link" data-nav="quests">← Retour au grimoire</button><div class="detailart theme-${q.theme}"><span class="emoji">${q.emoji}</span></div><div class="eyebrow" style="color:#9b7942">${esc(q.kind)} · ${esc(q.city)}</div><h2>${esc(q.title)}</h2><p class="desc">${esc(q.place)} · Difficulté ${'●'.repeat(q.difficulty)}${'○'.repeat(3-q.difficulty)} · Niveau requis ${q.unlock}</p><div>${tags(q)}</div><div class="rowgap" style="margin-top:12px"><button class="outline" data-action="map" data-id="${q.id}">Ouvrir dans Plans ↗</button><button class="softbtn" data-nav="journal">Voir nos souvenirs</button></div><div class="sectionrow"><h2>Étapes de la quête</h2><div class="subline">${checked.length} / ${q.steps.length}</div></div>${q.steps.map((step,i)=>`<button class="step" data-step="${i}" ${done?'disabled':''}><span class="check ${checked.includes(i)?'done':''}">${checked.includes(i)?'✓':''}</span><span><b>${esc(step[0])}</b><p>${esc(step[1])}</p></span></button>`).join('')}<div class="reward"><strong>Récompenses</strong>+${q.xp} XP · +${q.coins} pièces${q.hearts?` · +${q.hearts} cœur${q.hearts>1?'s':''}`:''}${q.badge?` · Badge possible : ${BADGES[q.badge][1]}`:''}</div>${done ? `<div class="notice">✓ Cette aventure a déjà été accomplie le ${new Date(state.completed[q.id].date).toLocaleDateString('fr-FR')}.</div>` : `<button class="mainbtn" data-action="finish" ${!all?'disabled':''}>${all?'Terminer la quête ✦':'Validez toutes les étapes'}</button><p class="desc">Les validations se font à la confiance : pas de géolocalisation imposée, pas de surveillance, seulement votre envie de vivre le moment.</p>`}</div>`;}
function settings(){return topSimple('Réglages du camp de base','Tout ce qu’il faut pour personnaliser, sauvegarder et protéger votre aventure.')+`<div class="container"><div class="setting"><h3>Vos noms d'aventuriers</h3><p>Ils apparaissent uniquement sur cet appareil.</p><label class="eyebrow" style="color:#9b7d46;display:block;margin-bottom:6px">Premier aventurier</label><input id="name1" maxlength="24" value="${esc(state.name1)}"><div style="height:10px"></div><label class="eyebrow" style="color:#9b7d46;display:block;margin-bottom:6px">Deuxième aventurier</label><input id="name2" maxlength="24" value="${esc(state.name2)}"><button class="mainbtn" style="margin-top:14px" data-action="names">Enregistrer</button></div><div class="setting"><h3>Sauvegarde & restauration</h3><p>Vos données restent locales. Exportez-les régulièrement pour les garder à l'abri.</p><button class="mainbtn" data-action="export">Exporter notre aventure</button><label class="secondary" style="display:block;text-align:center;margin-top:10px;cursor:pointer">Importer une sauvegarde<input id="importsave" type="file" accept="application/json,.json" style="display:none"></label></div><div class="setting"><h3>Confidentialité</h3><p>Aucun compte, aucune publicité, aucune collecte de progression. Seuls les liens Plans s’ouvrent à votre demande pour vous guider vers un lieu.</p></div><div class="setting"><h3>Réinitialiser</h3><p>Si vous recommencez à zéro, exportez d’abord une sauvegarde. L’action est irréversible sans fichier d’export.</p><button class="outline" data-action="reset">Recommencer l'aventure à zéro</button></div></div>`;}
function nav(){return v4HeaderNav();}
function render(){const app=document.getElementById('app'); const special=v4Render(); if(special!==null){app.innerHTML=special;v4RefreshPhotos();return;} let html=''; if(view==='home') html=home(); else if(view==='quests') html=questsView(); else if(view==='atlas') html=atlas(); else if(view==='journal') html=journal(); else if(view==='event') html=eventPage(); else if(view==='detail') html=detail(questById(selected)); else html=settings(); app.innerHTML=html + nav() + modal; document.title='Duo Quest — ' + ({home:'Accueil',quests:'Quêtes',atlas:'Explorer',journal:'Journal',event:'GTA VI',detail:'Aventure',settings:'Réglages'}[view]||'Duo Quest');}
function go(v){view=v; window.scrollTo(0,0); render();}
function exportSave(){const payload={...state,version:3,exported:new Date().toISOString()}; const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download='duo-quest-sauvegarde-'+new Date().toISOString().slice(0,10)+'.json'; document.body.append(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1200); notify('Sauvegarde prête à être enregistrée.');}
async function importSave(file){if(!file) return; try{const data=JSON.parse(await file.text()); if(!(data.version===1 || data.version===2 || data.version===3)) throw Error(); if(!confirm('Remplacer toute la progression actuelle par celle du fichier ?')) return; state={...defaultSave(),...data,event:{tasks:{},claimed:false,...(data.event||{})},name1:(data.name1||'Angèle').slice(0,24),name2:(data.name2||'Adrien').slice(0,24)}; save(); modal=''; go('home'); notify('Aventure restaurée avec succès.');}catch{notify('Sauvegarde invalide ou illisible.');}}
function finishQuest(){const q=questById(selected); if(!q || doneQuest(q)) return; const checked=state.started[q.id]||[]; if(!q.steps.every((_,i)=>checked.includes(i))) return; const oldLevel=level(); state.xp+=q.xp; state.coins+=q.coins; state.hearts += q.hearts||0; state.completed[q.id]={date:new Date().toISOString(),memory:''}; save(); const lvlUp=level()>oldLevel ? ` ✨ Vous passez au niveau ${level()} !` : ''; const badge=q.badge ? ` Nouveau badge possible : ${BADGES[q.badge][0]} ${BADGES[q.badge][1]}.` : ''; modal=`<div class="modalback"><div class="modal"><div class="big">🎉</div><div class="eyebrow" style="color:#9a7a3f">Aventure accomplie</div><h2>${esc(q.title)}</h2><p>Votre duo gagne <b>${q.xp} XP</b>, <b>${q.coins} pièces</b> et <b>${q.hearts||0} cœur${(q.hearts||0)>1?'s':''}</b>.${lvlUp}${badge}</p><p>Ajoutez une petite phrase souvenir si vous le souhaitez.</p><input id="memory" maxlength="240" placeholder="Votre souvenir à deux…"><button class="mainbtn" style="margin-top:14px" data-action="memory">Garder ce souvenir ♡</button></div></div>`; render();}
