function v6PreviewTheme(themeId){const t=V4_THEMES.find(x=>x[0]===themeId)||V4_THEMES[0];return t;}
function v6ThemeVars(themeId){const t=v6PreviewTheme(themeId), p=V6_THEME_PALETTES[t[4]]||V6_THEME_PALETTES.travel;const shift=Math.abs(hash(themeId))%4;const border=['#f6e0b2','#e6bf85','#dfb8a3','#f4d8ba'][shift];return `--album-bg:${p[0]};--album-accent:${p[1]};--album-detail:${p[2]};--album-paper:${p[3]};--album-border:${border};`}
function v6H(text){return esc(text)}
